/// <summary>
/// Populates table <c>METReserveEventOrdersTmp</c>.
/// </summary>
/// <param name = "_query">
/// <c>Query</c>.
/// </param>
/// <returns>
/// Table <c><METReserveEventOrdersTmp/c>.
/// </returns>
public static METReserveEventOrdersTmp populateTmp(Query _query)
{
    METReserveEventOrdersTmp reserveEventOrdersTmp;
    QueryBuildDataSource     qbdsSalesLine,
                             qbdsMETSalesTable;
    Map                      fieldMap;

    _query.clearAllFields();

    qbdsSalesLine = _query.dataSourceTable(tableNum(SalesLine));
    qbdsSalesLine.addSelectionField(fieldNum(SalesLine, InventTransId));

    qbdsMETSalesTable = _query.dataSourceTable(tableNum(METSalesTable));
    qbdsMETSalesTable.addSelectionField(fieldNum(METSalesTable, POLink));

    fieldMap = new Map(Types::String, Types::Container);

    fieldMap.insert(fieldStr(METReserveEventOrdersTmp, SalesLineTransId), [qbdsSalesLine.uniqueId(), fieldStr(SalesLine, InventTransId)]);
    fieldMap.insert(fieldStr(METReserveEventOrdersTmp, POLink), [qbdsMETSalesTable.uniqueId(), fieldStr(METSalesTable, POLink)]);

    Query::insert_recordset(reserveEventOrdersTmp, fieldMap, _query);

    return reserveEventOrdersTmp;
}
